findings.codeql_raw_query:
/**
 * @name Path traversal in file operations from command-line arguments
 * @description File operations using paths from command-line arguments without validation can lead to path traversal
 * @kind path-problem
 * @problem.severity high
 * @id py/path-traversal-cli
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Command-line arguments from argparse
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("argparse").getMember("ArgumentParser").getReturn().getMember("parse_args").getACall() and
      source.(DataFlow::AttrRead).getObject().getALocalSource() = call
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      (
        call = API::moduleImport("shutil").getMember(["copy", "copy2", "copytree", "move", "rmtree"]).getACall() or
        call = API::moduleImport("os").getMember(["remove", "unlink", "rmdir", "mkdir", "makedirs"]).getACall() or
        call = API::builtin("open").getACall()
      ) and
      sink = call.getArg(_)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal vulnerability from $@.", source.getNode(), "command-line argument"
